class Solution {
public:
    bool checkIfCanBreak(string s1, string s2) {
        int freq1[26] = {0}, freq2[26] = {0};
        for (char c : s1) freq1[c - 'a']++;
        for (char c : s2) freq2[c - 'a']++;

        int pref1 = 0, pref2 = 0;
        bool s1Breaks = true, s2Breaks = true;
        for (int i = 0; i < 26; i++) {
            pref1 += freq1[i];
            pref2 += freq2[i];
            if (pref1 > pref2) s1Breaks = false;
            if (pref2 > pref1) s2Breaks = false;
        }
        return s1Breaks || s2Breaks;
    }
};
